content.arguments:
{"command":"$sdk = 'C:\Users\a\AppData\Local\Android\Sdk'
"=== SDK 子目录内容 ==="
foreach ($d in 'sources','system-images','test-project','.temp') {
  $p = Join-Path $sdk $d
  "--- $d ---"
  if ((Test-Path $p) -and ((Get-ChildItem $p -Force -ErrorAction SilentlyContinue).Count -gt 0)) { Get-ChildItem $p -Recurse -Depth 1 -Force | ForEach-Object { $_.FullName } } else { "(空或不存在)" }
}
""
"=== 全盘搜 adb.exe（限常见目录） ==="
$found = @()
foreach ($root in 'C:\Program Files','C:\Program Files (x86)','C:\Users\a\AppData\Local','D:\','E:\') {
  if (Test-Path $root) {
    $found += Get-ChildItem $root -Filter adb.exe -Recurse -Depth 6 -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName }
  }
}
if ($found) { $found | Select-Object -First 20 } else { "什么都没搜到" }
""
"=== PATH 中的相关项 ==="
($env:PATH -split ';' | Where-Object { $_ -match 'android|java|jdk|gradle|platform' })
""
"=== 包管理器 ==="
foreach ($c in 'winget','choco','scoop') { $g = Get-Command $c -ErrorAction SilentlyContinue; if($g){"$c -> $($g.Source)"}else{"$c -> 无"} }
""
"=== 手机是否在线 ==="
try { Test-NetConnection -ComputerName 127.0.0.1 -Port 5037 -InformationLevel Quiet -WarningAction SilentlyContinue } catch { 'adb server端口探测失败' }","description":"深挖SDK内容与全盘搜索adb"}

