content.arguments:
{"command":"$sdk = 'D:\Android\Sdk'
"=== D:\Android\Sdk 结构 ==="
if (Test-Path $sdk) {
  Get-ChildItem $sdk -Force | ForEach-Object { '[{0}] {1}' -f ($(if($_.PSIsContainer){'DIR'}else{'FILE'})), $_.Name }
  ""
  "--- platforms ---"
  if (Test-Path "$sdk\platforms") { Get-ChildItem "$sdk\platforms" -Directory | ForEach-Object { $_.Name } } else { '无' }
  "--- build-tools ---"
  if (Test-Path "$sdk\build-tools") { Get-ChildItem "$sdk\build-tools" -Directory | ForEach-Object { $_.Name } } else { '无' }
  "--- platform-tools 版本 ---"
  if (Test-Path "$sdk\platform-tools\adb.exe") { & "$sdk\platform-tools\adb.exe" version | Select-Object -First 2 }
  "--- cmdline-tools ---"
  if (Test-Path "$sdk\cmdline-tools") { Get-ChildItem "$sdk\cmdline-tools" -Directory | ForEach-Object { $_.Name } } else { '无' }
} else { "不存在" }
""
"=== C:\Users\a\AppData\Local\Android\Sdk\sources\android-35 是否含 android.jar ==="
Test-Path 'C:\Users\a\AppData\Local\Android\Sdk\sources\android-35\android.jar'
Test-Path 'C:\Users\a\AppData\Local\Android\Sdk\platforms\android-35\android.jar'
""
"=== 找独立的 JDK17 ==="
foreach ($r in 'D:\','C:\Program Files\Java') {
  if (Test-Path $r) {
    Get-ChildItem $r -Filter 'jdk*' -Directory -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName }
    Get-ChildItem $r -Filter 'java.exe' -Recurse -Depth 4 -ErrorAction SilentlyContinue | Where-Object { $_.FullName -match 'bin\\java\.exe$' -and $_.FullName -notmatch 'Android Studio' } | Select-Object -First 10 -ExpandProperty FullName
  }
}
""
"=== AS 版本 ==="
$ver = Get-Content 'C:\Program Files\Android\Android Studio\product-info.json' -Raw -ErrorAction SilentlyContinue | ConvertFrom-Json
$ver.version
""
"=== 是否有 AVD ==="
Get-ChildItem "$env:USERPROFILE\.android\avd" -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }
""
"=== 环境变量持久值（用户级） ==="
[Environment]::GetEnvironmentVariable('ANDROID_HOME','User')
[Environment]::GetEnvironmentVariable('JAVA_HOME','User')
[Environment]::GetEnvironmentVariable('GRADLE_HOME','User')
"=== D:\Android 下还有啥 ==="
Get-ChildItem 'D:\Android' -Force -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }","description":"检查D盘SDK内容与独立JDK17"}

