content.arguments:
{"command":"$adb = 'D:\Android\Sdk\platform-tools\adb.exe'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$apk = 'D:\ai\gongzuo\新建文件夹\zhuli\zhuli-assistant-step2-build\app\build\outputs\apk\debug\app-debug.apk'
$dbp = "$env:TEMP\zhuli_probe.db"

$py = @'
import sqlite3, os, datetime
p = os.path.join(os.environ["TEMP"], "zhuli_probe.db")
con = sqlite3.connect(p)
def fmt(ms):
    return datetime.datetime.fromtimestamp(ms/1000).strftime("%m-%d %H:%M:%S") if ms else "-"
for r in con.execute("select id,inbox_id,due_at,status,fired_at,calendar_event_id from reminders order by id"):
    rid, inbox, due, status, fired, calev = r
    print(f"rem={rid} inbox={inbox} due={fmt(due)} dueMs={due} status={status} fired={fmt(fired)} calEv={calev}")
print("NOW:", datetime.datetime.now().strftime("%m-%d %H:%M:%S"))
'@
$py | Set-Content "$env:TEMP\zhuli_dump.py" -Encoding UTF8

function Dump {
  cmd /c "`"$adb`" exec-out run-as com.zhuli.app cat databases/zhuli_inbox.db > `"$dbp`"" | Out-Null
  (& python "$env:TEMP\zhuli_dump.py" 2>&1) -join "`n"
}
function NotifCount { (& $adb shell "dumpsys notification | grep -c 'pkg=com.zhuli.app'").Trim() }
function Alarms {
  $lines = (& $adb shell "dumpsys alarm") -join "`n" -split "`r?`n"
  $res = @()
  for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match 'com\.zhuli\.app') {
      $tag = ''; $ow = ''
      if ($lines[$i-1] -match 'origWhen\s+(\d+)') { $ow = $Matches[1] }
      if ($i+1 -lt $lines.Count -and $lines[$i+1] -match 'tag=(.*)') { $tag = $Matches[1].Trim() }
      if ($ow) { $res += "ALARM origWhen=$ow tag=$tag" }
    }
  }
  $res
}

"=== 1) 重装 ==="
& $adb install -r $apk 2>&1 | Select-Object -Last 1
Start-Sleep -Seconds 3
& $adb shell "cmd notification com.zhuli.app clear_all" 2>&1 | Out-Null
Start-Sleep -Seconds 1
"重装后通知数: $(NotifCount)"

"=== 2) 注入两条提醒（间隔 45 秒，错开响铃） ==="
& $adb shell "am start -n com.zhuli.app/com.zhuli.core.ShareReceiverActivity -a android.intent.action.SEND -t text/plain --es android.intent.extra.TEXT '1分钟后提醒我去扔垃圾测稍后按钮'" 2>&1 | Out-String
Start-Sleep -Seconds 45
& $adb shell "am start -n com.zhuli.app/com.zhuli.core.ShareReceiverActivity -a android.intent.action.SEND -t text/plain --es android.intent.extra.TEXT '1分钟后提醒我交作业测完成按钮'" 2>&1 | Out-String

$aDone = $false; $bDone = $false
$deadline = (Get-Date).AddSeconds(300)
while (-not ($aDone -and $bDone) -and (Get-Date) -lt $deadline) {
  Start-Sleep -Seconds 5
  $out = Dump
  if (-not $aDone -and $out -match "(?m)^rem=(\d+) .*status=fired fired=\d{2}-\d{2} \d{2}:\d{2}:\d{2}.*?") {
    # 找第一条新提醒（A，id 最小的 scheduled 变 fired 的）
  }
  # A: 最早的 scheduled 行；若其变为 fired 且尚未处理 → SNOOZE
  $mA = [regex]::Match($out, '(?m)^rem=(\d+) .*status=scheduled')
  if (-not $aDone -and -not $mA.Success) { # 所有 scheduled 都空？不对：还有 B 在 scheduled
  }
  break
}
""
"(占位) 下一段单独循环处理"","description":"重装并注入两条测试提醒","timeoutMs":300000}

