```kotlin
class ReminderActionReceiver : BroadcastReceiver() {

    override fun onReceive(context: Context, intent: Intent) {
        val id = intent.getLongExtra(EXTRA_REMINDER_ID, 0L)
        // === TEMP-TRACE（验收用，验证完删除）===
        fun trace(s: String) = try {
            java.io.FileWriter(java.io.File(context.filesDir, "ra_trace.txt"), true).use { it.write("$s\n") }
        } catch (_: Throwable) {}
