p = os.path.join(os.environ["TEMP"], "zhuli_probe.db")
con = sqlite3.connect(p)
def fmt(ms):
    return datetime.datetime.fromtimestamp(ms/1000).strftime("%m-%d %H:%M:%S") if ms else "-"
for r in con.execute("select id,inbox_id,due_at,status,fired_at,calendar_event_id from reminders order by id"):
    rid, inbox, due, status, fired, calev = r
    print(f"rem={rid} inbox={inbox} due={fmt(due)} dueMs={due} status={status} fired={fmt(fired)} calEv={calev}")
print("NOW:", datetime.datetime.now().strftime("%m-%d %H:%M:%S"))
'@
$py | Set-Content "$env:TEMP\zhuli_dump.py" -Encoding UTF8

function Dump {
  cmd /c "`"$adb`" exec-out run-as com.zhuli.app cat databases/zhuli_inbox.db > `"$dbp`"" | Out-Null
  (& python "$env:TEMP\zhuli_dump.py" 2>&1) -join "`n"
}
function Alarms {
  $all = (& $adb shell "dumpsys alarm") -join "`n"
  $lines = $all -split "`r?`n"
  for ($i = 1; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match 'tag=\*walarm\*:com\.zhuli\.reminder\.(\w+)') {
      $ow = ''
      if ($lines[$i-1] -match 'origWhen\s+(\d+)') { $ow = $Matches[1] }
      "ALARM[$($Matches[1])] origWhen=$ow"
    }
  }
}

"=== T0 预备：唤醒/解锁/回桌面 ==="
& $adb shell input keyevent 224 2>&1 | Out-Null
& $adb shell input keyevent 82 2>&1 | Out-Null
Start-Sleep -Milliseconds 600
& $adb shell input keyevent 3 2>&1 | Out-Null
Start-Sleep -Milliseconds 700
$baseOut = Dump
$globalMax = 0
foreach ($m in [regex]::Matches($baseOut, '(?m)^rem=(\d+) ')) { $g = [int]$m.Groups[1].Value; if ($g -gt $globalMax) { $globalMax = $g } }
"基线最大 rem id = $globalMax，$(Get-Date -Format 'HH:mm:ss')"

"=== 注入 S（稍后） ==="
& $adb shell "am start -n com.zhuli.app/com.zhuli.core.ShareReceiverActivity -a android.intent.action.SEND -t text/plain --es android.intent.extra.TEXT '1分钟后提醒我按稍后按钮'" 2>&1 | Out-String

$Sid = 0; $oldDue = 0L; $tapS = 0L; $okS = $false
$dl = (Get-Date).AddSeconds(140)
while ((Get-Date) -lt $dl) {
  Start-Sleep -Milliseconds 500
  & $adb shell input keyevent 224 2>&1 | Out-Null
  $out = Dump
  $now = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
  $fresh = $null
  foreach ($m in [regex]::Matches($out, '(?m)^rem=(\d+) inbox=\d+.*? dueMs=(\d+) status=([\w-]+)')) {
    $rid = [int]$m.Groups[1].Value
    if ($rid -gt $globalMax -and [int]([Math]::Abs([long]$m.Groups[2].Value - $now)) -le 30 -and $m.Groups[3].Value -eq 'fired') {
      if (-not $fresh -or $rid -lt $fresh.id) { $fresh = [pscustomobject]@{id=$rid; due=[long]$m.Groups[2].Value} }
    }
  }
  if ($fresh) {
    $Sid = $fresh.id; $oldDue = $fresh.due; $tapS = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
    "S 触发 rem=$Sid 旧due=$oldDue —— 连点 (711,136)"
    & $adb shell input tap 711 136 2>&1 | Out-Null
    Start-Sleep -Milliseconds 350; & $adb shell input tap 711 136 2>&1 | Out-Null
    Start-Sleep -Milliseconds 900; & $adb shell input tap 711 136 2>&1 | Out-Null
    Start-Sleep -Seconds 2
    $after = Dump
    $row = [regex]::Match($after, "(?m)^rem=$Sid .*?")
    $ms = [regex]::Match($after, "(?m)^rem=$Sid inbox=\d+.*? dueMs=(\d+) status=([\w-]+)")
    $expected = $tapS + 600000L
    $delta = [Math]::Abs([long]$ms.Groups[1].Value - $expected)
    $notifNow = (& $adb shell "dumpsys notification | grep -c 'pkg=com.zhuli.app'").Trim()
    if ([int]$ms.Groups[2].Value -eq 0 -and $delta -le 8000) {
      "✅ SNOOZE 生效: 新dueMs=$($ms.Groups[1].Value) (期望≈$expected, Δ$($delta)ms) status=scheduled 通知数=$notifNow"
      $okS = $true
    } else {
      "❌ S 未生效: $($ms.Groups[1].Value)/$($ms.Groups[2].Value) notif=$notifNow Δ=$delta"
    }
    break
  }
}
if (-not $okS) { "S 阶段未达成，稍后人工复核" }
""
"闹钟(S 后): "; Alarms

"=== 注入 D（完成） ==="
$baseOut2 = Dump
$gm2 = $globalMax
foreach ($m in [regex]::Matches($baseOut2, '(?m)^rem=(\d+) ')) { $g = [int]$m.Groups[1].Value; if ($g -gt $gm2) { $gm2 = $g } }
& $adb shell "am start -n com.zhuli.app/com.zhuli.core.ShareReceiverActivity -a android.intent.action.SEND -t text/plain --es android.intent.extra.TEXT '1分钟后提醒我按完成按钮'" 2>&1 | Out-String

$Did = 0; $calevD = 0; $tapD = 0L; $okD = $false
$dl = (Get-Date).AddSeconds(140)
while ((Get-Date) -lt $dl) {
  Start-Sleep -Milliseconds 500
  & $adb shell input keyevent 224 2>&1 | Out-Null
  $out = Dump
  $now = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
  $fresh = $null
  foreach ($m in [regex]::Matches($out, '(?m)^rem=(\d+) inbox=\d+.*? dueMs=(\d+) status=([\w-]+)')) {
    $rid = [int]$m.Groups[1].Value
    if ($rid -gt $gm2 -and [int]([Math]::Abs([long]$m.Groups[2].Value - $now)) -le 30 -and $m.Groups[3].Value -eq 'fired') {
      if (-not $fresh -or $rid -lt $fresh.id) { $fresh = [pscustomobject]@{id=$rid; due=[long]$m.Groups[2].Value} }
    }
  }
  if ($fresh) {
    $Did = $fresh.id; $tapD = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
    $cm = [regex]::Match($out, "(?m)^rem=$Did .*calEv=(\d+)")
    $calevD = [long]$cm.Groups[1].Value
    $beforeRows = @(& $adb shell "content query --uri content://com.android.calendar/events --projection _id:title --where `"_id=$calevD`"" 2>&1 | Where-Object {$_ -match 'Row:'}).Count
    "D 触发 rem=$Did calEv=$calevD 日历前=$beforeRows —— 连点 (284,136)"
    & $adb shell input tap 284 136 2>&1 | Out-Null
    Start-Sleep -Milliseconds 350; & $adb shell input tap 284 136 2>&1 | Out-Null
    Start-Sleep -Milliseconds 900; & $adb shell input tap 284 136 2>&1 | Out-Null
    Start-Sleep -Seconds 2
    $after = Dump
    $ms = [regex]::Match($after, "(?m)^rem=$Did inbox=\d+.*? dueMs=(\d+) status=([\w-]+)")
    $afterRows = @(& $adb shell "content query --uri content://com.android.calendar/events --projection _id:title --where `"_id=$calevD`"" 2>&1 | Where-Object {$_ -match 'Row:'}).Count
    $notifNow = (& $adb shell "dumpsys notification | grep -c 'pkg=com.zhuli.app'").Trim()
    if ([int]$ms.Groups[2].Value -eq 3 -and $afterRows -eq 0 -and $notifNow -eq '0') {
      "✅ DONE 生效: status=done 日历事件已删($beforeRows→$afterRows) 通知数=0"
      $okD = $true
    } else {
      "❌ D 未生效: status=$($ms.Groups[2].Value) 日历=$beforeRows→$afterRows notif=$notifNow"
    }
    break
  }
}
""
"=== 终态 DB ==="
Dump
"闹钟(D 后): "; Alarms","description":"新鲜匹配同刻双击验证SNOOZE与DONE两个动作全链路","timeoutMs":330000}

