$adb = 'D:\Android\Sdk\platform-tools\adb.exe'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$dbp = "$env:TEMP\zhuli_probe.db"
$ui = "$env:TEMP\ui_live.xml"

function Dump {
  cmd /c "`"$adb`" exec-out run-as com.zhuli.app cat databases/zhuli_inbox.db > `"$dbp`"" | Out-Null
  (& python "$env:TEMP\zhuli_dump.py" 2>&1) -join "`n"
}

# === 0) 清掉所有旧 zhuli 通知，保证横幅是「孤零零」的一条 ===
& $adb shell "cmd notification com.zhuli.app clear_all" 2>&1 | Out-Null
Start-Sleep -Milliseconds 800
"旧通知已清"

# === 1) 快照 rem id ===
$snap = @{}
foreach ($m in [regex]::Matches((Dump), '(?m)^rem=(\d+) ')) { $snap[[int]$m.Groups[1].Value] = $true }
"注入前已有 rem id: $(@($snap.Keys | Sort-Object) -join ',')"

# === 2) 唤醒/解锁/回桌面 ===
& $adb shell input keyevent 224 2>&1 | Out-Null
& $adb shell input keyevent 82 2>&1 | Out-Null
Start-Sleep -Milliseconds 400
& $adb shell "input swipe 608 2300 608 700 280" 2>&1 | Out-Null
Start-Sleep -Milliseconds 700
& $adb shell input keyevent 3 2>&1 | Out-Null
Start-Sleep -Milliseconds 900
"前台: $((& $adb shell 'dumpsys window | grep mCurrentFocus').Trim())"

# === 3) 注入（只此一条，无遮挡）===
& $adb shell "am start -n com.zhuli.app/com.zhuli.core.ShareReceiverActivity -a android.intent.action.SEND -t text/plain --es android.intent.extra.TEXT '1分钟后提醒我按完成按钮'" 2>&1 | Out-String

# === 4) 锁真正新行 ===
$Did = 0
for ($i = 0; $i -lt 20; $i++) {
  Start-Sleep -Seconds 2
  $o = Dump
  $newest = 0
  foreach ($m in [regex]::Matches($o, '(?m)^rem=(\d+) ')) {
    $v = [int]$m.Groups[1].Value
    if (-not $snap.ContainsKey($v) -and $v -gt $newest) { $newest = $v }
  }
  if ($newest -gt 0) { $Did = $newest; break }
}
if ($Did -eq 0) { "!! 未发现新行"; exit }
"🔒 新行 id=$Did $(Get-Date -Format 'HH:mm:ss')"

# === 5) 等 fired；触发瞬间：UI树定位「完成」→ 精确点击；最多重试 12 次 ===
$tapped = $false
$dl = (Get-Date).AddSeconds(150)
while ((Get-Date) -lt $dl) {
  Start-Sleep -Milliseconds 350
  & $adb shell input keyevent 224 2>&1 | Out-Null
  $o = Dump
  if ($o -match "(?m)^rem=$Did .*status=fired") {
    "🔔 fired @ $(Get-Date -Format 'HH:mm:ss') —— UI 树定位「完成」按钮"
    $target = ''
    for ($try = 0; $try -lt 12; $try++) {
      & $adb shell uiautomator dump /sdcard/ui.xml 2>&1 | Out-Null
      & $adb pull /sdcard/ui.xml $ui 2>&1 | Out-Null
      if (Test-Path $ui) {
        try {
          [xml]$x = Get-Content $ui -Raw -Encoding UTF8
          $bestNode = $null; $bestScore = 999
          foreach ($node in $x.SelectNodes('//node')) {
            $tx = $node.GetAttribute('text')
            if ($tx -and ($tx -match '完成' -or $tx -match '稍后')) {
              $desc = $node.GetAttribute('content-desc')
              $score = 0
              if ($tx -match '^完成$') { $score = 0 } elseif ($tx -match '完成') { $score = 1 } elseif ($tx -match '稍后') { $score = 2 }
              if ($desc) { $score += 5 }
              if ($score -lt $bestScore) { $bestScore = $score; $bestNode = $node }
            }
          }
          if ($bestNode) {
            $b = $bestNode.GetAttribute('bounds')
            if ($b -match '\[(\d+),(\d+)\]\[(\d+),(\d+)\]') {
              $cx = [int](($Matches[1] + $Matches[3]) / 2); $cy = [int](($Matches[2] + $Matches[4]) / 2)
              "找到节点: text='$($bestNode.GetAttribute('text'))' desc='$($bestNode.GetAttribute('content-desc'))' bounds=$b 中心=($cx,$cy)"
              & $adb shell input tap $cx $cy 2>&1 | Out-Null
              $target = "tap($cx,$cy)"
              break
            }
          }
        } catch {}
      }
      Start-Sleep -Milliseconds 200
    }
    if (-not $target) { "!! UI 树没找到按钮，兜底点两次 (325,118)"; & $adb shell input tap 325 118 2>&1 | Out-Null }
    $tapped = $true; break
  }
}
if (-not $tapped) { "!! 未等到触发"; exit }

Start-Sleep -Seconds 3
