  Start-Sleep -Seconds 2
  $o = Dump
  $nm = [regex]::Matches($o, '(?m)^rem=(\d+) inbox=\d+.*? dueMs=(\d+) status=([a-z]+)')
  if ($nm.Count -gt 0) {
    $rid = [int]$nm[0].Groups[1].Value
    $dueStr = [DateTimeOffset]::FromUnixTimeMilliseconds([long]$nm[0].Groups[2].Value).ToLocalTime().ToString('MM-dd HH:mm')
    break
  }
}
if ($rid -eq 0) { "!! 未入库"; exit }
"🔒 新行 id=$rid 解析出的到期时间: $dueStr $(Get-Date -Format 'HH:mm:ss')"
if ($dueStr -notmatch '11-20 09:30') { "⚠️ 时间解析与预期不符，但继续：验证的是重排逻辑而非具体时刻" }

# 等闹钟注册
Start-Sleep -Seconds 8
$al = (& $adb shell "dumpsys alarm") -join "`n"
$lines = $al -split "`r?`n"
$fireBefore = ''
for ($i = 1; $i -lt $lines.Count; $i++) {
  if ($lines[$i] -match 'com\.zhuli\.app' -and $lines[$i] -match 'origWhen\s+(\d+)') {
    if ($i+1 -lt $lines.Count -and $lines[$i+1] -match 'tag=\*walarm\*:com\.zhuli\.reminder\.FIRE') {
      $fireBefore = [DateTimeOffset]::FromUnixTimeMilliseconds([long]$Matches[1]).ToLocalTime().ToString('MM-dd HH:mm:ss')
      break
    }
  }
}
