$l2 = $al2 -split "`r?`n"
$fireAfter = ''
$hbAfter = $false
for ($i = 1; $i -lt $l2.Count; $i++) {
  if ($l2[$i] -match 'com\.zhuli\.app' -and $l2[$i] -match 'origWhen\s+(\d+)') {
    $t = [DateTimeOffset]::FromUnixTimeMilliseconds([long]$Matches[1]).ToLocalTime().ToString('MM-dd HH:mm:ss')
    if ($i+1 -lt $l2.Count -and $l2[$i+1] -match 'tag=\*walarm\*:com\.zhuli\.reminder\.(\w+)') {
      if ($Matches[1] -eq 'FIRE') { $fireAfter = $t }
      if ($Matches[1] -eq 'HEARTBEAT') { $hbAfter = $true }
    }
  }
}
"重启后 FIRE 闹钟: $fireAfter"
"心跳闹钟重新注册: $hbAfter"
""
$dv = Dump
$dm = [regex]::Match($dv, "(?m)^rem=$rid inbox=\d+.*? dueMs=(\d+) status=([a-z]+)")
"DB 行状态: $($dm.Groups[2].Value)（期望 scheduled）due=$($dm.Groups[1].Value)"
""
if ($fireAfter -match '11-20 09:30' -and $hbAfter -and $dm.Groups[2].Value -eq 'scheduled') {
  "✅✅✅ BootReceiver 重排通过：重启后闹钟自动归位（FIRE=$fireAfter）＋心跳恢复＋库状态保留"
} else {
  "❌ 判定: FIRE=$fireAfter hb=$hbAfter st=$($dm.Groups[2].Value)"
}

