    Start-Sleep -Milliseconds 600
    try {
      return (& python "$env:TEMP\zhuli_dump.py" 2>&1) -join "`n"
    } catch {}
    Start-Sleep -Milliseconds 1500
  }
  return '<DUMP_FAILED>'
}
""
"=== 稳定后库内容 ==="
DumpRetry","description":"等待系统启动稳定后重读数据库","timeoutMs":420000}

