function ZhuliAlarms {
  $al = (& $adb shell "dumpsys alarm") -join "`n"
  $lines = $al -split "`r?`n"
  for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match 'Alarm\{[^}]*origWhen\s+(\d+)[^}]*com\.zhuli\.app\}') {
      $ow = [long]$Matches[1]
      $t = [DateTimeOffset]::FromUnixTimeMilliseconds($ow).ToLocalTime().ToString('MM-dd HH:mm:ss')
      $tag = ''
      if ($i+1 -lt $lines.Count -and $lines[$i+1] -match 'tag=\*walarm\*:com\.zhuli\.reminder\.(\w+)') { $tag = $Matches[1] }
      "ALARM[$tag] $t"
    }
  }
}

"=== 重启前 zhuli 闹钟 ==="
ZhuliAlarms

""
"=== 执行 reboot ==="
& $adb reboot
for ($i = 0; $i -lt 90; $i++) {
  Start-Sleep -Seconds 5
  $bc = & $adb shell "getprop sys.boot_completed" 2>&1
  $up = & $adb shell "cat /proc/uptime" 2>&1 | Select-Object -First 1
  if (($bc -match '^\s*1$') -and ($up -match '([\d.]+)') -and [double]$Matches[1] -ge 100) { break }
}
