content.arguments:
{"content":"package com.zhuli.core

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.net.Uri
import android.util.Log
import com.google.android.gms.mlkit.vision.common.InputImage
import com.google.android.gms.mlkit.vision.text.TextRecognition
import com.google.android.gms.mlkit.vision.text.chinese.ChineseTextRecognizerOptions
import com.google.android.gms.tasks.Tasks
import java.io.File
import java.text.SimpleDateFormat
import java.util.Calendar
import java.util.Date
import java.util.Locale
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit
import java.util.regex.Pattern

/**
 * 第 6 步 · 支付账单截图的端侧 OCR。
 *
 * 引擎选型：**ML Kit 中文文字识别（Google Play 服务版）**——
 * - 「敏感不出机」红线要求 OCR 必须端侧；走手机上已装好的 Play 服务，模型按需下载，
 *   不打包进 APK（不增重）；
 * - 代价：首次识别要联网拉中文模型（墙内可能失败）→ 失败时条目照常入库、字段留空，
 *   不让一次 OCR 失败打断分享主链路（与链接抓取失败的兜底同构）；
 * - 该引擎是现成最优解；若 Play 模型被墙，实测后可切 bundled 版（模型进 APK，加重约 15MB）。
 *
 * 产出契约（对应需求 §2.4-② 截图通道）：**金额 / 商户 / 时间**。
 * v1 边界：规则解析只认常见账单版式（¥/金额/商户标签/常见时间格式）；认错版式落「未识别」，不硬猜。
 */
object BillOcr {

    private const val TAG = "zhuli.billocr"
    private const val MAX_DIM_OCR = 1600      // OCR 输入最大边长
    private const val MAX_DIM_THUMB = 512     // 缩略图最大边长（D3：不留原图）

    private val io = Executors.newSingleThreadExecutor()

    data class Result(
        val amount: Double,
        val merchant: String,
        val paidAtMs: Long,
        val lines: List<String>
    )

    // ==================== 对外入口 ====================

    /**
     * 分享入口统一调用：后台线程跑 OCR，完成后回调。
     * 回调发生在 Activity 可能已经 finish 之后 —— 实现里只用 applicationContext，不要持有 Activity。
     */
    fun recognizeAsync(context: Context, uri: Uri, onResult: (Result?) -> Unit) {
        val app = context.applicationContext
        io.execute {
            val bmp = try { decodeBounded(app, uri, MAX_DIM_OCR) } catch (t: Throwable) { null }
            if (bmp == null) {
                Log.w(TAG, "decode failed")
                onResult(null)
                return@execute
            }
            val client = TextRecognition.getClient(ChineseTextRecognizerOptions.Builder().build())
            try {
                val visionText = Tasks.await(client.process(InputImage.fromBitmap(bmp, 0)), 90, TimeUnit.SECONDS)
                val lines = buildList {
                    for (ln in visionText.text.split('\n')) {
                        if (ln.isNotBlank()) add(ln.trim())
                    }
                }
                onResult(parse(lines))
            } catch (t: Throwable) {
                Log.w(TAG, "ocr failed (play model download may be blocked)", t)
                onResult(null)
            } finally {
                client.close()
            }
        }
    }

    /** 纯函数：识别出的文本行 → 金额/商户/时间。可离线回放、可单测。 */
    fun parse(lines: List<String>): Result {
        return Result(
            amount = parseAmount(lines),
            merchant = parseMerchant(lines),
            paidAtMs = parseTime(lines),
            lines = lines
        )
    }

    /** 缩略图（D3：只留小图，路径随第 15 步加密备份带走）。 */
    fun saveThumbnail(context: Context, id: Long, sourceUri: Uri): String? {
        val dir = File(context.filesDir, "zhuli_media").apply { mkdirs() }
        val out = File(dir, "b$id.png")
        return try {
            val bmp = decodeBounded(context, sourceUri, MAX_DIM_THUMB) ?: return null
            val ok = bmp.compress(Bitmap.CompressFormat.PNG, 90, out.outputStream())
            if (ok) out.absolutePath else null
        } catch (t: Throwable) {
            Log.w(TAG, "thumbnail failed", t)
            null
        }
    }

    // ==================== 金额 ====================

    private val P_MONEY_SYM = Pattern.compile("(?:¥|￥|\\$)\\s*(\\d+(?:\\.\\d{1,2})?)")
    private val P_MONEY_UNIT = Pattern.compile("(\\d+(?:\\.\\d{1,2})?)\\s*(元|块钱|块|RMB|rmb)")
    private val P_ANY_NUM = Pattern.compile("(\\d+(?:\\.\\d{1,2})?)")
    private val CTX_MONEY = listOf("元", "块", "费", "支", "收", "额", "账", "交易", "付款", "消费", "入账", "工资", "花", "价")

    private fun parseAmount(lines: List<String>): Double {
        // ① 最可靠：¥ / ￥ / $ 紧跟的数
        for (ln in lines) {
            val m = P_MONEY_SYM.matcher(ln)
            if (m.find()) {
                val v = m.group(1)?.toDoubleOrNull() ?: return 0.0
                return if (v in 0.01..9_999_999.0) v else 0.0
            }
        }
        // ② 数字后跟单位：32 元 / 32 块
        for (ln in lines) {
            val m = P_MONEY_UNIT.matcher(ln)
            if (m.find()) {
                val v = m.group(1)?.toDoubleOrNull() ?: return 0.0
                return if (v in 0.01..9_999_999.0) v else 0.0
            }
        }
        // ③ 裸数字，但前后 10 字内有金额语境（「支出」「交易成功」这类版式）
        for (ln in lines) {
            val m = P_ANY_NUM.matcher(ln)
            while (m.find()) {
                val v = m.group(1)?.toDoubleOrNull() ?: continue
                if (v <= 0.0 || v > 9_999_999.0) continue
                val lo = maxOf(0, m.start() - 10)
                val hi = minOf(ln.length, m.end() + 10)
                val win = ln.substring(lo, hi)
                if (CTX_MONEY.any { win.contains(it) }) return v
            }
        }
        return 0.0
    }

    // ==================== 商户 ====================

    private val P_MERCHANT_TAG = Pattern.compile("商户(?:名称|名)?\\s*[:：]?\\s*([^，。,\\s]{2,24})")
    private val P_RECEIVER_TAG = Pattern.compile("(?:收款方|对方(?:户名)?|商户全称)\\s*[:：]?\\s*([^，。,\\s]{2,24})")

    private fun parseMerchant(lines: List<String>): String {
        // ① 明标了「商户」的版式（支付宝/微信账单通用）
        for (ln in lines) {
            val m = P_MERCHANT_TAG.matcher(ln)
            if (m.find()) return m.group(1).trim()
        }
        for (ln in lines) {
            val m = P_RECEIVER_TAG.matcher(ln)
            if (m.find()) return m.group(1).trim()
        }
        // ② 没标的版式：挑最长的一行中文（排掉金额行/时间行/标题行）
        var best = ""
        for (ln in lines) {
            if (ln.length !in 2..24) continue
            if (!ln.any { it.code in 0x4E00..0x9FFF }) continue          // 必须含中文
            if (P_ANY_NUM.matcher(ln).find()) continue                    // 带数字的先让位给金额
            if (ln.contains('¥') || ln.contains('￥')) continue
            if (P_TIME_A.matcher(ln).find()) continue
            if (ln.length > best.length) best = ln
        }
        return best
    }

    // ==================== 时间 ====================

    private val P_TIME_A = Pattern.compile(
        "(\\d{4}\\s*[-/.年]\\s*\\d{1,2}\\s*[-/.月]\\s*\\d{1,2}\\s*[日号]?\\s*(?:[T\\s]\\s*)?\\d{1,2}:\\d{2}(?::\\d{2})?)"
    )
    private val P_TIME_B = Pattern.compile(
        "(\\d{1,2}\\s*月\\s*\\d{1,2}\\s*[日号]?\\s*\\d{1,2}:\\d{2}(?::\\d{2})?)"
    )
    private val FMT_CJK = arrayOf("yyyy年M月d日 HH:mm:ss", "yyyy年M月d日 HH:mm", "M月d日 HH:mm")
    private val FMT_ISO = arrayOf("yyyy-MM-dd HH:mm:ss", "yyyy-MM-dd HH:mm", "yyyy-MM-dd'T'HH:mm", "MM-dd HH:mm")

    private fun parseTime(lines: List<String>): Long {
        for (ln in lines) {
            val matched = P_TIME_A.matcher(ln).takeIf { it.find() }?.group(1)
                ?: P_TIME_B.matcher(ln).takeIf { it.find() }?.group(1)
                ?: continue
            val ts = tryParse(matched, FMT_CJK) ?: tryParse(normalizeTs(matched), FMT_ISO)
            if (ts > 0) return ts
        }
        return 0L
    }

    /** CJK 形态不直接匹配 ISO 格式器，先抹平再按 ISO 试一遍，双保险。 */
    private fun normalizeTs(raw: String): String = raw
        .replace('年', '-')
        .replace('月', '-')
        .replace("日", "")
        .replace("号", " ")
        .replace('/', '-')
        .replace('.', '-')

    private fun tryParse(raw: String, formats: Array<String>): Long {
        for (f in formats) {
            try {
