{"content":"package com.zhuli.core

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.widget.Toast
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * 分享菜单入口（Share Target）。
 * 其他 App「分享 → zhuli助理」时唤起：文字直接入库，图片走第 6 步端侧 OCR 账单链路。
 *
 * 安全口径（对应需求 §2.6-A3 只收不发）：
 * - 只在本地落库，绝不代为回复/转发来源 App；
 * - 图片 OCR 在手机本地完成（Play 服务版 ML Kit），原始图片不出机、只留小缩略图（需求 D3）；
 * - 视频等其余类型暂拒收（第 8/11 步再接）。
 */
class ShareReceiverActivity : Activity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        if (intent?.action != Intent.ACTION_SEND) {
            setResult(RESULT_CANCELED); finish(); return
        }
        val type = intent.type
        if (type != null && type.startsWith("image/")) {
            handleImage()
            return
        }
        if (type != "text/plain") {
            Toast.makeText(this, "暂时只收文字和图片，视频后面跟上", Toast.LENGTH_SHORT).show()
            setResult(RESULT_CANCELED); finish(); return
        }

        val text = (intent.getCharSequenceExtra(Intent.EXTRA_TEXT)?.toString() ?: "").trim()
        if (text.isEmpty()) {
            Toast.makeText(this, "没读到内容", Toast.LENGTH_SHORT).show()
            setResult(RESULT_CANCELED); finish(); return
        }

        // 第 3 步：文本含链接 → 走链接链路（命中敏感特征只存不抓，否则读正文出摘要）
        if (LinkExtractor.hasUrl(text)) {
            LinkExtractor.handle(this, text) { msg ->
                runOnUiThread { Toast.makeText(this@ShareReceiverActivity, msg, Toast.LENGTH_SHORT).show() }
            }
            setResult(RESULT_OK); finish(); return
        }

        val pkg = callingPackage ?: applicationContext.packageName
        val label = try {
            packageManager.getApplicationLabel(packageManager.getApplicationInfo(pkg, 0)).toString()
        } catch (t: Throwable) { "" }
        val db = InboxDatabase(this)
        db.insert(
            InboxRecord(
                source = InboxRecord.SOURCE_SHARE,
                packageName = pkg,
                appLabel = label,
                title = "分享",
                text = text,
                receivedAt = System.currentTimeMillis()
            )
        )
        // 第 4 步：分享进来的话也要立刻结构化（分类/时间/金额）
        ExtractPipeline.trigger(applicationContext)
        Toast.makeText(this, "已收下：${text.take(18)}${if (text.length > 18) "…" else ""}", Toast.LENGTH_SHORT).show()
        setResult(RESULT_OK); finish()
    }

    // ==================== 图片链路（第 6 步 · 端侧 OCR 账单） ====================

    private fun handleImage() {
        val first = imageUri(intent!!)
        if (first == null) {
            Toast.makeText(applicationContext, "没读到图片", Toast.LENGTH_SHORT).show()
            setResult(RESULT_CANCELED); finish(); return
        }
        val extra = maxOf(imageCount(), 1) - 1
        val pkg = callingPackage ?: applicationContext.packageName
        val label = try {
            packageManager.getApplicationLabel(packageManager.getApplicationInfo(pkg, 0)).toString()
        } catch (t: Throwable) { "" }

        // 先入库占位：分享链路秒回执，识别结果后台回写（用户立刻能看见「一条在进来」）
        val db = InboxDatabase(this)
        val id = db.insert(
            InboxRecord(
                source = InboxRecord.SOURCE_SHARE,
                packageName = pkg,
                appLabel = label,
                title = "图片",
                text = "[图片处理中]${if (extra > 0) "（共 ${extra + 1} 张，先处理第一张）" else ""}",
                receivedAt = System.currentTimeMillis()
            )
        )

        Toast.makeText(applicationContext, "已收下图片，正在本机识别…", Toast.LENGTH_SHORT).show()
        setResult(RESULT_OK); finish()

        // Activity 此刻已 finish：回调里只用 applicationContext，不持有本 Activity
        BillOcr.recognizeAsync(this, first) { r ->
            val db2 = InboxDatabase(applicationContext)
            try {
                val text: String
                val fields: ExtractFields
                if (r == null || (r.amount <= 0.0 && r.merchant.isBlank())) {
                    // OCR 不可用（Play 模型被墙）或版式没认出：照常入库、诚实留痕、不再重试
                    text = "图片：未识别出账单内容"
                    fields = ExtractFields(
                        category = InboxRecord.CAT_OTHER,
                        deadlineTs = 0L,
                        amount = 0.0,
                        note = "图片OCR未识别出账单（引擎不可用或版式不支持）"
                    )
                } else {
                    text = buildString {
                        if (r.merchant.isNotBlank()) append(r.merchant).append(' ')
                        append("¥").append(fmtAmount(r.amount))
                        if (r.paidAtMs > 0) append(' ').append(fmtTime(r.paidAtMs))
                    }.trim()
                    fields = ExtractFields(
                        category = InboxRecord.CAT_FINANCE,
                        deadlineTs = 0L,
                        amount = r.amount,
                        note = buildString {
                            append("账单：").append(if (r.merchant.isNotBlank()) r.merchant else "未标注商户")
                            if (r.paidAtMs > 0) append(' ').append(fmtTime(r.paidAtMs))
                        }.trim()
                    )
                }
                db2.applyBill(id, text, fields)
                // D3 媒体存储策略：只留 512px 缩略图并记路径，原图一律不保存
                BillOcr.saveThumbnail(applicationContext, id, first)?.let { p ->
                    db2.setMediaPath(id, p)
                }
            } catch (t: Throwable) {
                android.util.Log.e("zhuli.share", "bill ocr callback failed id=$id", t)
            } finally {
                try { db2.close() } catch (_: Throwable) {}
            }
        }
    }

    /** 多图分享走 ClipData、单图走 EXTRA_STREAM，两者都兼容，只取第一张。 */
    @Suppress("DEPRECATION")
    private fun imageUri(intent: Intent): Uri? {
        val fromClip = intent.clipData?.takeIf { it.itemCount > 0 }?.getItemAt(0)?.uri
        if (fromClip != null) return fromClip
        return intent.getParcelableExtra(Intent.EXTRA_STREAM) as? Uri
    }

    @Suppress("DEPRECATION")
    private fun imageCount(): Int {
        val viaClip = intent?.clipData?.itemCount ?: 0
        val viaStream = try {
            intent?.getParcelableArrayListExtra<Uri>(Intent.EXTRA_STREAM)?.size ?: 0
        } catch (_: Throwable) { 0 }
        return maxOf(viaClip, viaStream)
    }

    private fun fmtAmount(v: Double) =
        if (v == v.toLong().toDouble()) v.toLong().toString()
        else String.format(Locale.US, "%.2f", v)

    private fun fmtTime(ms: Long) =
        SimpleDateFormat("M-d HH:mm", Locale.getDefault()).format(Date(ms))
