content.arguments:
{"command":"Add-Type -AssemblyName System.IO.Compression.FileSystem
$cache = "$env:USERPROFILE\.gradle\caches\modules-2\files-2.1\com.google.android.gms"
$tmp = "$env:TEMP\mlkit_jar"
if (Test-Path $tmp) { Remove-Item $tmp -Recurse -Force }
New-Item -ItemType Directory -Path $tmp | Out-Null
foreach ($name in 'play-services-mlkit-text-recognition-chinese','play-services-mlkit-text-recognition-common') {
  $aar = Get-ChildItem "$cache\$name" -Recurse -Filter '*.aar' | Select-Object -First 1
  "===== $($aar.Name) ====="
  $z = [System.IO.Compression.ZipFile]::OpenRead($aar.FullName)
  $entry = $z.Entries | Where-Object { $_.FullName -eq 'classes.jar' } | Select-Object -First 1
  if ($entry) {
    $dest = Join-Path $tmp ($name + '_classes.jar')
    [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $dest, $true)
    $jz = [System.IO.Compression.ZipFile]::OpenRead($dest)
    foreach ($e in $jz.Entries) {
      if ($e.FullName -match '\.class$') { "  $($e.FullName)" }
    }
    $jz.Dispose()
  } else { "  (无 classes.jar)" }
  $z.Dispose()
}","description":"解包AAR内层jar并列出全部类名"}

