                java.io.FileOutputStream(java.io.File(app.filesDir, "ocr_trace.txt"), true)
                    .use { it.write("$s\n".toByteArray()) }
            } catch (_: Throwable) {}
            diag("start uri=$uri")
            val bmp = try { decodeBounded(app, uri, MAX_DIM_OCR) } catch (t: Throwable) { null }
            if (bmp == null) {
                Log.w(TAG, "decode failed")
                diag("decode_failed")
                onResult(null)
                return@execute
            }
            diag("decode_ok ${bmp.width}x${bmp.height}")
            val client = TextRecognition.getClient(ChineseTextRecognizerOptions.Builder().build())
            try {
                val visionText = Tasks.await(client.process(InputImage.fromBitmap(bmp, 0)), 90, TimeUnit.SECONDS)
                val lines = buildList {
                    for (ln in visionText.text.split('\n')) {
                        if (ln.isNotBlank()) add(ln.trim())
                    }
                }
                diag("ocr_ok lines=${lines.size} text=${lines.joinToString(" | ").take(200)}")
                onResult(parse(lines))
            } catch (t: Throwable) {
                Log.w(TAG, "ocr failed (play model download may be blocked)", t)
                diag("ocr_failed ${t.javaClass.name}: ${t.message}")
                onResult(null)
            } finally {
                client.close()
            }
        }
