    }
    val exp = byCat.filter { it.first != Ledger.DIR_INCOME }
    val inc = byCat.filter { it.first == Ledger.DIR_INCOME }
    val expSum = exp.sumOf { it.third.second }
    return buildString {
        append("${win.label}记了 ${byCat.sumOf { it.third.first }} 笔账：支出合计 ¥${fmtMoney(expSum)}")
        if (inc.isNotEmpty()) append("，收入 ¥${fmtMoney(inc.sumOf { it.third.second })}")
        append("。\n支出明细：").append(exp.joinToString("\n") {
            "· ${it.second} ¥${fmtMoney(it.third.second)}（${it.third.first} 笔）"
        })
        if (inc.isNotEmpty()) {
            append("\n收入明细：").append(inc.joinToString("\n") {
                "· ${it.second} ¥${fmtMoney(it.third.second)}（${it.third.first} 笔）"
            })
        }
    }
}

