{"command":"$adb = 'D:\Android\Sdk\platform-tools\adb.exe'
function ResolveIt {
  param([string]$action, [string]$data)
  $r = & $adb shell "cmd package resolve-activity --brief -a $action" 2>&1
  if ($data) { $r = & $adb shell "cmd package resolve-activity --brief -a $action -d $data" 2>&1 }
  ($r | Out-String).Trim().Split("`n") | Where-Object { $_ -match '/' } | Select-Object -Last 1
}
