{"command":"$adb = 'D:\Android\Sdk\platform-tools\adb.exe'
foreach ($pkg in 'com.zte.powersavemode', 'com.zte.heartyservice') {
  $lines = @(& $adb shell "dumpsys package $pkg" 2>$null)
  "===== $pkg（$($lines.Count) 行）====="
  if ($lines.Count -lt 5) { "输出过少，可能异常：" ; ($lines -join "`n").Substring(0, [Math]::Min(200, ($lines -join "`n").Length)); continue }
  $comps = @()
  foreach ($ln in $lines) {
    foreach ($m in [regex]::Matches($ln, '[A-Za-z0-9_.]+/[A-Za-z0-9_.$]+')) { $comps += $m.Groups[1].Value }
  }
  $uniq = $comps | Sort-Object -Unique
  "去重组件数: $($uniq.Count)"
