  $uniq | Where-Object { $_ -match 'Power|Saver|Save|Boot|Auto|Protect|White|Battery|Charge|Bg|Life|Guard|Optimizer' } | Select-Object -First 25
}","description":"修正数组处理重导组件清单找白名单入口"}

