{"content":"package com.zhuli.core

import android.app.Activity
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Build
import android.os.PowerManager
import android.provider.Settings
import android.util.Log

/**
 * 第 13 步 B4 · 保活白名单引导（复用手机自带设置，不申请特殊权限、不写自启动）。
 *
 * 背景（真机实证）：`adb reboot` 后 MyOS 不向本应用投递 BOOT_COMPLETED，闹钟不会自动重排；
 * 任意一次打开 App 会由 sweep 兜底重建。要让「重启也叫得醒」，只能靠用户把 App 加进
 * 系统自启动白名单 + 电池优化豁免 —— 这是 OEM 行为，App 无法用代码代替，只能**引导**。
 *
 * 设计口径：
 * - **只复用手机自带组件**：全部跳系统/厂商设置的现成页面，不引入任何第三方保活库、
 *   不做后台拉活、不申请自启动类的私有权限（守住「不做流氓软件」的底线）；
 * - **真实检测 + 诚实标注**：电池优化豁免有公开 API（[PowerManager.isIgnoringBatteryOptimizations]）
 *   可以直接查；**自启动开关没有任何公开 API**，一律标「需手动确认」，绝不假装能查；
 * - 候选入口按机型优先级排列，逐个 try，全失败退「应用详情页」（所有 ROM 必有）。
 */
object StartupGuard {

    private const val TAG = "zhuli.keepalive"

    /** 跳转结果：命中的是哪一类入口，供壳里给用户一句准话。 */
    data class JumpResult(val ok: Boolean, val via: String)

    // ==================== 状态检测（能查的才查） ====================

    /** 电池优化豁免：true=已豁免（系统不会轻易掐死），false=仍被优化。 */
    fun batteryExempt(ctx: Context): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) return true
        val pm = ctx.getSystemService(Context.POWER_SERVICE) as? PowerManager ?: return true
        return try {
            pm.isIgnoringBatteryOptimizations(ctx.packageName)
        } catch (t: Throwable) {
            Log.w(TAG, "query battery exemption failed", t)
            false
        }
    }

    /**
     * 面板展示用的状态行。
     * 自启动一栏**只能标「需手动确认」**——Android 没有公开 API 可查 OEM 自启动白名单，
     * 与其编一个假绿勾，不如让用户自己看一眼。
     */
    fun statusLines(ctx: Context): List<Pair<String, String>> = listOf(
        "电池优化" to if (batteryExempt(ctx)) "✅ 已豁免" else "❌ 仍受限（省电可能掐后台）",
        "自启动" to "⚠️ 需手动确认（系统无公开接口）",
        "重启后" to "提醒靠「打开 App 即重建」兜底，加白名单后才能开机自动恢复"
    )

    // ==================== 跳转（复用手机自带页面） ====================

    /** 系统应用详情页：所有 ROM 都有，最可靠的兜底。 */
