content.arguments:
{"content":"package com.zhuli.core

import android.content.ClipData
import android.content.ClipboardManager
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Build
import android.os.PowerManager
import android.provider.Settings
import android.util.Log

/**
 * 第 13 步 B4 · 保活白名单引导（复用手机自带设置，不申请特殊权限、不做后台拉活）。
 *
 * ## 为什么必须有这一块
 * 真机实证：`adb reboot` 后 MyOS 不向本应用投递 BOOT_COMPLETED，闹钟不会自动重排；
 * 打开 App 会由 sweep 兜底重建，但要「开机就自己活过来」，只能靠系统级的
 * **自启动白名单 + 电池优化豁免**。这是 OEM 行为，App 无法用代码代替，只能引导。
 *
 * ## 真机摸底的硬结论（2026-11-19，NX733J / MyOS）
 * 厂商省电页（`com.zte.powersavemode` 的 AppManagerActivity / SettingsActivity / PowerSaveModeActivity）
 * 全部受 **`zte.permission.LAUNCH_POWER_SAVER_ACTIVITY`** 签名级权限保护，
 * 第三方应用与 shell 均抛 SecurityException —— **不可达**，不再尝试，免得给用户弹一串失败。
 *
 * 因此本类只保留三条**真正可用**的路：
 * 1. 电池优化豁免：AOSP 标准入口，可直连系统弹窗（一次点击完成，最见效）；
 * 2. 应用详情页：所有 ROM 必有，用户可在其中找到「耗电详情」等系统项；
 * 3. 复制指引：厂商自启动开关没有公开 API 也无通用入口，把路径写成文字让用户自己照着点。
 *
 * ## 原则
 * - **能查的才查**：电池豁免有公开 API 就显示真实状态；自启动一律标「需手动确认」，绝不假绿勾；
 * - **不装流氓软件**：不引入保活库、不常驻前台、不申请自启动私有权限。
 */
object StartupGuard {

    private const val TAG = "zhuli.keepalive"

    /** 跳转结果：ok=是否成功打开；via=给用户看的一句准话。 */
    data class JumpResult(val ok: Boolean, val via: String)

    // ==================== 状态检测 ====================

    /** 电池优化豁免：true=已豁免（省电不会轻易掐死），false=仍被优化。 */
    fun batteryExempt(ctx: Context): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) return true
        val pm = ctx.getSystemService(Context.POWER_SERVICE) as? PowerManager ?: return true
        return try {
            pm.isIgnoringBatteryOptimizations(ctx.packageName)
        } catch (t: Throwable) {
            Log.w(TAG, "query battery exemption failed", t)
            false
        }
    }

    /**
     * 面板展示用的状态行。
     * 自启动一栏**只能标「需手动确认」**——Android 没有公开 API 可查 OEM 自启动白名单，
     * 与其编一个假绿勾骗人，不如让人自己看一眼。
     */
    fun statusLines(ctx: Context): List<Pair<String, String>> = listOf(
        "电池优化" to if (batteryExempt(ctx)) "✅ 已豁免（省电不会轻易掐后台）"
        else "❌ 仍受限（息屏/省电时后台可能被掐）",
        "自启动" to "⚠️ 需手动确认（系统无公开接口可查）",
        "重启后" to "未加白名单时靠「打开 App 即重建闹钟」兜底；加了才能开机自动恢复"
    )

    // ==================== 三条可用路径 ====================

    /**
     * 电池优化豁免：直连系统弹窗（一次点击）；不行退电池优化列表页；再退应用详情。
     * 直连弹窗需要 manifest 声明 REQUEST_IGNORE_BATTERY_OPTIMIZATIONS（普通权限，已在清单内）。
     */
    fun openBatterySettings(ctx: Context): JumpResult {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) {
            return JumpResult(false, "系统版本较低，无需单独设置电池豁免")
        }
        val direct = Intent(
            Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,
            Uri.parse("package:${ctx.packageName}")
        )
        if (tryStart(ctx, direct, "电池豁免弹窗")) return JumpResult(true, "已打开「电池优化豁免」——点「允许」即可")

