    /**
     * 面板展示用的状态行。
     * 自启动一栏**只能标「需手动确认」**——Android 没有公开 API 可查 OEM 自启动白名单，
     * 与其编一个假绿勾，不如让用户自己看一眼。
     */
    fun statusLines(ctx: Context): List<Pair<String, String>> = listOf(
        "电池优化" to if (batteryExempt(ctx)) "✅ 已豁免" else "❌ 仍受限（省电可能掐后台）",
        "自启动" to "⚠️ 需手动确认（系统无公开接口）",
        "重启后" to "提醒靠「打开 App 即重建」兜底，加白名单后才能开机自动恢复"
    )

    // ==================== 跳转（复用手机自带页面） ====================

    /** 系统应用详情页：所有 ROM 都有，最可靠的兜底。 */
    fun openAppDetails(ctx: Context): Boolean = tryStart(
        ctx,
        Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS, Uri.parse("package:${ctx.packageName}")),
        "应用详情"
    ).ok

    /**
     * 电池优化豁免：优先直达「要不要豁免」弹窗（一次点击完成），
     * 退到电池优化列表页（用户自己在列表里找本 App），再退应用详情。
     * 注意：直达弹窗需要 manifest 声明 REQUEST_IGNORE_BATTERY_OPTIMIZATIONS（普通权限，已在清单内）。
     */
    fun openBatterySettings(ctx: Context): JumpResult {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) return JumpResult(false, "系统版本过低，无需设置")
        val direct = Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,
            Uri.parse("package:${ctx.packageName}"))
        if (tryStart(ctx, direct, "电池豁免弹窗").ok) return JumpResult(true, "电池豁免弹窗")
        val list = Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS)
        if (tryStart(ctx, list, "电池优化列表").ok) return JumpResult(true, "电池优化列表（请手动找到本应用）")
        val ok = openAppDetails(ctx)
        return JumpResult(ok, if (ok) "应用详情（请自行进入电池设置）" else "未找到可用入口")
    }

    /**
     * 厂商自启动/后台管理。候选顺序按机型优先级排；每一项先试**显式组件**（最准，不会弹歧义选择器），
     * 再试动作名（换 ROM 版本仍可能命中）；全失败退应用详情页。
     */
    fun openAutoStart(ctx: Context): JumpResult {
        for (c in AUTO_START_CANDIDATES) {
            if (c.pkg != null && c.cls != null) {
                val explicit = Intent().apply {
                    component = android.content.ComponentName(c.pkg, c.cls)
                }
                if (tryStart(ctx, explicit, "${c.name}（显式）").ok) return JumpResult(true, c.name)
            }
            if (c.action != null) {
                if (tryStart(ctx, Intent(c.action), "${c.name}（动作）").ok) return JumpResult(true, c.name)
            }
        }
        val ok = openAppDetails(ctx)
        return JumpResult(
            ok,
            if (ok) "未找到厂商自启动页，已打开「应用详情」——请在其中找「自启动/后台管理」" else "未找到可用入口"
        )
    }

    /** 一键走完：先自启动页，再电池豁免（壳里也可分两个按钮，这里留作快捷入口用）。 */
    fun openBoth(ctx: Context): JumpResult {
        val a = openAutoStart(ctx)
        if (a.ok) return a
        return openBatterySettings(ctx)
    }

    /**
     * 厂商自启动入口候选。
     * 真机 `cmd package resolve-activity` 实测结论：
     * - `AppManagerActivity`（应用省电管理）唯一命中，是最可能的「后台运行/自启动」页；
     * - `AppManualOptimizeActivity` 会落到 ResolverActivity（多匹配→弹选择器），
     *   所以必须用**显式组件**点名 `.appsmartoptimizer.AppManualOptimizeActivity`，不能只给动作名；
     * - `SettingsActivity` 是省电总入口，作最后兜底。
     */
    private data class Candidate(
        val name: String,
        val pkg: String?,
        val cls: String?,
        val action: String?
    )

    private val ZTE_PKG = "com.zte.powersavemode"

    private val AUTO_START_CANDIDATES = listOf(
        Candidate(
            "MyOS 应用省电管理",
            ZTE_PKG, "$ZTE_PKG.appspowersave.AppManagerActivity",
            "com.zte.powersavemode.intent.action.AppManagerActivity"
        ),
        Candidate(
            "MyOS 应用手动优化",
            ZTE_PKG, "$ZTE_PKG.appsmartoptimizer.AppManualOptimizeActivity",
            null   // 动作名有歧义（会弹选择器），只走显式组件
        ),
        Candidate(
            "MyOS 省电设置",
            ZTE_PKG, "$ZTE_PKG.main.SettingsActivity",
            "com.zte.powersavemode.intent.action.SettingsActivity"
        )
    )

    // ==================== 小工具 ====================

    /**
     * 起一个系统页面：ActivityNotStarted / SecurityException / 无匹配组件都算正常失败，
     * 只记一条日志返回 false，让调用方换下一个候选。绝不因为跳转失败崩溃。
     */
    private fun tryStart(ctx: Context, intent: Intent, name: String): JumpResult {
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        return try {
            ctx.startActivity(intent)
            Log.i(TAG, "opened: $name")
            JumpResult(true, name)
        } catch (t: Throwable) {
            Log.w(TAG, "open failed: $name (${t.javaClass.simpleName})")
            JumpResult(false, name)
        }
    }
}

