    /**
     * 面板展示用的状态行。
     * 自启动一栏**只能标「需手动确认」**——Android 没有公开 API 可查 OEM 自启动白名单，
     * 与其编一个假绿勾骗人，不如让人自己看一眼。
     */
    fun statusLines(ctx: Context): List<Pair<String, String>> = listOf(
        "电池优化" to if (batteryExempt(ctx)) "✅ 已豁免（省电不会轻易掐后台）"
        else "❌ 仍受限（息屏/省电时后台可能被掐）",
        "自启动" to "⚠️ 需手动确认（系统无公开接口可查）",
        "重启后" to "未加白名单时靠「打开 App 即重建闹钟」兜底；加了才能开机自动恢复"
    )

    // ==================== 三条可用路径 ====================

    /**
     * 电池优化豁免：直连系统弹窗（一次点击）；不行退电池优化列表页；再退应用详情。
     * 直连弹窗需要 manifest 声明 REQUEST_IGNORE_BATTERY_OPTIMIZATIONS（普通权限，已在清单内）。
     */
    fun openBatterySettings(ctx: Context): JumpResult {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) {
            return JumpResult(false, "系统版本较低，无需单独设置电池豁免")
        }
        val direct = Intent(
            Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,
            Uri.parse("package:${ctx.packageName}")
        )
        if (tryStart(ctx, direct, "电池豁免弹窗")) return JumpResult(true, "已打开「电池优化豁免」——点「允许」即可")

        val list = Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS)
        if (tryStart(ctx, list, "电池优化列表")) {
            return JumpResult(true, "已打开电池优化列表——请找到「zhuli助理」并选「不优化」")
        }
        return jumpOrDetails(ctx)
    }

    /** 打开系统「应用详情」页（所有 ROM 都有，最可靠兜底）。 */
    fun openAppDetails(ctx: Context): Boolean =
        tryStart(ctx, Intent(
            Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
            Uri.parse("package:${ctx.packageName}")
        ), "应用详情")

    /** 一键走：先电池豁免（唯一能真跳的），失败退应用详情。 */
    fun openBest(ctx: Context): JumpResult {
        val r = openBatterySettings(ctx)
        if (r.ok) return r
        return jumpOrDetails(ctx)
    }

    // ==================== 手动指引（复制走） ====================

    /**
     * 按机型给一段可复制的手动设置指引。
     * 厂商自启动开关既无 API 也无通用深链，写到剪贴板让用户照着点，是最实际的办法。
     */
    fun guideText(ctx: Context): String {
        val brand = (Build.MANUFACTURER ?: "").lowercase()
        val path = when {
            brand.contains("nubia") || brand.contains("zte") ->
                "设置 → 电池 → 省电管理 / 应用省电 → 找到「zhuli助理」→ 允许后台运行、加入自启动白名单"
            brand.contains("xiaomi") || brand.contains("redmi") ->
                "设置 → 应用设置 → 应用管理 → zhuli助理 → 自启动 打开；省电策略设为「无限制」"
            brand.contains("huawei") || brand.contains("honor") ->
                "设置 → 应用 → 应用启动管理 → zhuli助理 → 关闭「自动管理」，手动开允许自启动/后台活动"
            brand.contains("oppo") || brand.contains("oneplus") || brand.contains("realme") ->
                "设置 → 电池 → 应用耗电管理 → zhuli助理 → 允许后台运行；并在「自启动」里打开"
            brand.contains("vivo") || brand.contains("iqoo") ->
                "设置 → 电池 → 后台高耗电 → 允许 zhuli助理；i管家 → 自启动 里也打开"
            else ->
                "设置 → 电池/应用管理 → 找到「zhuli助理」→ 允许后台运行，并加入自启动白名单"
        }
        return buildString {
            appendLine("【zhuli助理 · 保活设置指引】")
            appendLine("1. 自启动：$path")
            appendLine("2. 电池优化：设置 → 电池 → 电池优化 → 搜「zhuli助理」→ 选「不优化」")
            appendLine("（也可以直接点 App 里的「电池豁免」按钮，一步直达）")
            appendLine()
            append("设好后重启手机，提醒无需打开 App 也会自动恢复。")
        }
    }

    /** 把指引复制到剪贴板，返回是否成功。 */
    fun copyGuide(ctx: Context): Boolean {
        return try {
            val cm = ctx.getSystemService(Context.CLIPBOARD_SERVICE) as? ClipboardManager ?: return false
            cm.setPrimaryClip(ClipData.newPlainText("zhuli 保活指引", guideText(ctx)))
            true
        } catch (t: Throwable) {
            Log.w(TAG, "copy guide failed", t)
            false
        }
    }

    // ==================== 小工具 ====================

    private fun jumpOrDetails(ctx: Context): JumpResult {
        return if (openAppDetails(ctx)) {
            JumpResult(true, "已打开「应用详情」——可在其中进入电池/耗电等系统项")
        } else {
            JumpResult(false, "没找到可用的系统设置入口")
        }
    }

    /**
     * 起系统页面：ActivityNotFound / SecurityException / 无匹配组件都算正常失败，
     * 只记一条日志返回 false，让调用方换下一条路。绝不因为跳转失败崩溃。
     */
    private fun tryStart(ctx: Context, intent: Intent, name: String): Boolean {
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        return try {
            ctx.startActivity(intent)
            Log.i(TAG, "opened: $name")
            true
        } catch (t: Throwable) {
            Log.w(TAG, "open failed: $name (${t.javaClass.simpleName})")
            false
        }
    }
}

