{"command":"$out = "$env:TEMP\voice_test.wav"
try {
  Add-Type -AssemblyName System.Speech
  $sp = New-Object System.Speech.Synthesis.SpeechSynthesizer
  "可用语音："
  $sp.GetInstalledVoices() | ForEach-Object { "  $($_.VoiceInfo.Name) / $($_.VoiceInfo.Culture)" }
  # 优先挑中文语音
  $zh = $sp.GetInstalledVoices() | Where-Object { $_.VoiceInfo.Culture.Name -like 'zh*' } | Select-Object -First 1
  if ($zh) {
    $sp.SelectVoice($zh.VoiceInfo.Name)
    "使用中文语音: $($zh.VoiceInfo.Name)"
    $text = '明天下午三点提醒我开会'
  } else {
    "无中文语音，用默认语音说中文（可能念不准）"
    $text = '3 minutes later remind me'
  }
  $sp.SetOutputToWaveFile($out)
  $sp.Speak($text)
  $sp.Dispose()
  "生成: $out ($([math]::Round((Get-Item $out).Length/1KB)) KB)"
} catch {
  "SAPI 不可用: $($_.Exception.Message)"
}","description":"用Windows语音合成生成中文测试音频"}

