{"file_path":"D:\ai\gongzuo\新建文件夹\zhuli\zhuli-assistant-step2\core\ShareReceiverActivity.kt","new_string":"    // ==================== 语音链路（第 8 步 · 本地转写） ====================

    /**
     * 语音消息：先入库占位并秒回执，后台把音频复制进私有目录再本地转写；
     * 转写成功 → 文本走同一条提取流水线（分类/期限/金额）+ 入账，音频随即删除（D3 只留文字）；
     * 转写失败 → 条目保留「未转写」并记下音频路径，等第 9 步云兜底或用户重试。
     */
    private fun handleAudio(type: String) {
        val uri = imageUri(intent!!)
        if (uri == null) {
            Toast.makeText(applicationContext, "没读到语音文件", Toast.LENGTH_SHORT).show()
            setResult(RESULT_CANCELED); finish(); return
        }
        val pkg = callingPackage ?: applicationContext.packageName
        val label = try {
            packageManager.getApplicationLabel(packageManager.getApplicationInfo(pkg, 0)).toString()
        } catch (t: Throwable) { "" }

        val db = InboxDatabase(this)
        val id = db.insert(
            InboxRecord(
                source = InboxRecord.SOURCE_SHARE,
                packageName = pkg,
                appLabel = label,
                title = "语音",
                text = "[语音转写中]",
                receivedAt = System.currentTimeMillis()
            )
        )

        Toast.makeText(applicationContext, "已收下语音，正在本机转写…", Toast.LENGTH_SHORT).show()
        setResult(RESULT_OK); finish()

        // Activity 已 finish：回调只用 applicationContext
        thread {
            var audioFile: java.io.File? = null
            try {
                audioFile = copyToPrivate(id, uri, type)
                if (audioFile == null) {
                    writeAudioResult(id, "[语音] 读取失败", "语音文件读取失败", keepPath = "")
                    return@thread
                }
                val durMs = VoiceNote.durationMs(audioFile)
                VoiceNote.transcribeAsync(applicationContext, audioFile) { r ->
                    // 回到工作线程收尾，避免在主线程碰数据库
                    thread {
                        if (r.ok) {
                            val fields = ExtractPipeline.extract(r.text)
                            val db2 = InboxDatabase(applicationContext)
                            try {
                                db2.applyVoice(id, r.text, fields, "")
                                if (fields.amount > 0) {
                                    Ledger.ingest(db2, id, r.text, fields.amount, System.currentTimeMillis())
                                }
                            } finally {
                                try { db2.close() } catch (_: Throwable) {}
                            }
                            // D3：转写成功即删音频，只留文字
                            try { audioFile.delete() } catch (_: Throwable) {}
                        } else {
                            val secs = if (durMs > 0) "（${durMs / 1000}s）" else ""
                            writeAudioResult(
                                id,
                                "[语音$secs] 未转写：${r.note}",
                                "语音未转写：${r.note}",
                                keepPath = audioFile.absolutePath
                            )
                        }
                    }
                }
            } catch (t: Throwable) {
                android.util.Log.e("zhuli.share", "audio handle failed id=$id", t)
                writeAudioResult(id, "[语音] 处理失败", "语音处理失败：${t.javaClass.simpleName}", keepPath = "")
            }
        }
    }

    /** 把分享来的音频复制进 App 私有目录，返回文件；失败返回 null。 */
    private fun copyToPrivate(id: Long, uri: Uri, mime: String): java.io.File? {
        val ext = when {
            mime.contains("mpeg") || mime.contains("mp3") -> "mp3"
            mime.contains("m4a") || mime.contains("mp4") -> "m4a"
            mime.contains("amr") -> "amr"
            mime.contains("ogg") -> "ogg"
            mime.contains("wav") || mime.contains("x-wav") -> "wav"
            else -> "audio"
        }
        return try {
            val dir = java.io.File(filesDir, "zhuli_media").apply { mkdirs() }
            val out = java.io.File(dir, "a$id.$ext")
            contentResolver.openInputStream(uri)?.use { input ->
                out.outputStream().use { output -> input.copyTo(output, 64 * 1024) }
            } ?: return null
            if (out.length() <= 0L) null else out
        } catch (t: Throwable) {
            android.util.Log.w("zhuli.share", "copy audio failed", t)
            null
        }
    }

    /** 转写失败/读取失败：诚实落库，保留路径（若有）供后续重试。 */
    private fun writeAudioResult(id: Long, displayText: String, note: String, keepPath: String) {
        try {
            val db2 = InboxDatabase(applicationContext)
            try {
                db2.applyVoice(
                    id, displayText,
                    ExtractFields(category = InboxRecord.CAT_OTHER, deadlineTs = 0L, amount = 0.0, note = note),
                    keepPath
                )
            } finally {
                try { db2.close() } catch (_: Throwable) {}
            }
        } catch (t: Throwable) {
            android.util.Log.e("zhuli.share", "write audio result failed id=$id", t)
        }
    }

