/**
 * 候选识别服务：先试系统默认（null），再逐个试本机注册的 RecognitionService。
 * 为什么要挨个试：部分 ROM（本机 MyOS 实测）没设默认识别服务，直接 `createSpeechRecognizer(ctx)`
 * 会立刻回 `ERROR_CLIENT`；但包管理器里其实有别的应用注册的识别服务（如翻译类 App），
 * 用 `createSpeechRecognizer(ctx, ComponentName)` 点名还能用上 —— 属「复用手机已有能力」。
 */
private fun candidates(ctx: Context): List<android.content.ComponentName?> {
    val list = mutableListOf<android.content.ComponentName?>(null)
    try {
        ctx.packageManager
            .queryIntentServices(Intent(android.speech.RecognitionService.SERVICE_INTERFACE), 0)
            .forEach { ri ->
                ri.serviceInfo?.let { si ->
                    list.add(android.content.ComponentName(si.packageName, si.name))
                }
            }
    } catch (t: Throwable) {
        Log.w(TAG, "query recognition services failed", t)
    }
    return list
}

private fun tryCandidates(
    ctx: Context,
    file: File,
    list: List<android.content.ComponentName?>,
    idx: Int,
    onDone: (Result) -> Unit
) {
    if (idx >= list.size) {
        onDone(Result(false, "", "本机所有语音识别服务都不可用"))
        return
    }
    val comp = list[idx]
    val name = comp?.let { "${it.packageName}/${it.className.substringAfterLast('.')}" } ?: "系统默认"
    Log.i(TAG, "try recognizer #$idx: $name")
    attempt(ctx, file, comp) { r ->
        if (r.ok) onDone(r)
        else tryCandidates(ctx, file, list, idx + 1, onDone)
    }
}

