                out.write("whisper-1".toByteArray())
                out.write(nl.toByteArray())
                out.write(("--$boundary--$nl").toByteArray())
                out.flush()
            }

            val code = conn.responseCode
            if (code != 200) {
                val err = try { conn.errorStream?.bufferedReader()?.readText()?.take(80) } catch (_: Throwable) { "" }
