{"command":"$root = 'D:\ai\gongzuo\新建文件夹\zhuli'
$stage = "$env:TEMP\zhuli_pack\zhuli"
if (Test-Path "$env:TEMP\zhuli_pack") { Remove-Item "$env:TEMP\zhuli_pack" -Recurse -Force }
New-Item -ItemType Directory -Path $stage -Force | Out-Null

# 源码（core）与文档全带
Copy-Item "$root\zhuli-assistant-step2" "$stage\zhuli-assistant-step2" -Recurse -Force
Get-ChildItem $root -File -Filter '*.md' | ForEach-Object { Copy-Item $_.FullName $stage -Force }

# 验收壳工程：只带源码/配置/截图/夹具，剔除 build 与 .gradle 产物
$build = "$root\zhuli-assistant-step2-build"
New-Item -ItemType Directory -Path "$stage\zhuli-assistant-step2-build" -Force | Out-Null
foreach ($item in @('app','gradle','settings.gradle.kts','build.gradle.kts','gradle.properties','local.properties','README.md')) {
  $p = Join-Path $build $item
  if (Test-Path $p) { Copy-Item $p "$stage\zhuli-assistant-step2-build\$item" -Recurse -Force }
}
# 剔除构建产物与缓存
foreach ($junk in @('app\build','.gradle','build')) {
  $p = Join-Path "$stage\zhuli-assistant-step2-build" $junk
  if (Test-Path $p) { Remove-Item $p -Recurse -Force }
}

$zip = 'D:\ai\gongzuo\新建文件夹\交接_2026-11-19\zhuli-源码.zip'
if (Test-Path $zip) { Remove-Item $zip -Force }
Compress-Archive -Path "$env:TEMP\zhuli_pack\zhuli" -DestinationPath $zip -CompressionLevel Optimal
"新 zip: $([math]::Round((Get-Item $zip).Length/1KB)) KB"
""
"=== 核对关键文件是否入包 ==="
Add-Type -AssemblyName System.IO.Compression.FileSystem
$z = [System.IO.Compression.ZipFile]::OpenRead($zip)
foreach ($k in 'BillOcr.kt','Ledger.kt','StartupGuard.kt','VoiceNote.kt','ShareReceiverActivity.kt','InboxDatabase.kt','MainActivity.kt','build.gradle.kts') {
  $hit = $z.Entries | Where-Object { $_.FullName -like "*$k" } | Select-Object -First 1
  "{0,-26} {1}" -f $k, $(if($hit){'✓ 在包内'}else{'✗ 缺失'})
}
"条目总数: $($z.Entries.Count)"
$z.Dispose()","description":"重打包最新源码并核验关键文件入包","timeoutMs":180000}

