Compress-Archive -Path "$env:TEMP\zhuli_pack\zhuli" -DestinationPath $zip -CompressionLevel Optimal
"新 zip: $([math]::Round((Get-Item $zip).Length/1KB)) KB"
""
"=== 核对关键文件是否入包 ==="
Add-Type -AssemblyName System.IO.Compression.FileSystem
$z = [System.IO.Compression.ZipFile]::OpenRead($zip)
foreach ($k in 'BillOcr.kt','Ledger.kt','StartupGuard.kt','VoiceNote.kt','ShareReceiverActivity.kt','InboxDatabase.kt','MainActivity.kt','build.gradle.kts') {
